        }
        body {
            font-family: var(--font-family);
            background-color: transparent;
            margin: 0;
            padding: 10px;
        }
        .status-card {
            background: var(--card-bg);
            border-left: 5px solid var(--border-color);
            border-radius: 8px;
            padding: 18px;
            color: var(--text-primary);
            width: 380px;
            box-shadow: 0 4px 15px var(--shadow-color);
            box-sizing: border-box;
        }
        .card-header {
            color: var(--title-color);
            font-size: 18px;
            font-weight: bold;
            border-bottom: 1px solid #3b4261;
            padding-bottom: 8px;
            margin-bottom: 12px;
        }
        .card-body .property {
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            align-items: center;
            padding: 8px 0;
            font-size: 15px;
        }
        .property .property-name {
            color: var(--text-secondary);
        }
        .property .property-value {
            font-weight: 600;
            text-shadow: 0 0 5px rgba(191, 158, 227, 0.6);
        }
        .progress-bar-container {
            width: 100%;
            background-color: var(--progress-bar-bg);
            border-radius: 5px;
            height: 10px;
            overflow: hidden;
            margin-top: 5px;
        }
        .progress-bar-value {
            background-color: var(--border-color);
            height: 100%;
            width: 0%;
            transition: width 0.5s ease-in-out;
            border-radius: 5px;
        }
        .divider-top {
            margin-top: 8px;
            border-top: 1px dashed #3b4261;
            padding-top: 12px;
        }
    </style>
</head>
<body>
    <div class="status-card" id="status-card">
        <div class="card-header">顾客驯化系统 (CDS)</div>
        <div class="card-body">
            <div class="property">
                <div class="property-name">❖ 驯化阶段</div>
                <div class="property-value" id="guke-status">警惕抗拒</div>
            </div>
            <div class="property" style="padding-bottom: 2px;">
                <div class="property-name">❖ 驯化值</div>
                <div class="property-value" id="guke-value">0 / 100</div>
            </div>
            <div class="progress-bar-container">
                <div id="guke-value-bar" class="progress-bar-value" style="width: 0%;"></div>
            </div>
            <div class="property divider-top">
                <div class="property-name">❖ 戒断反应</div>
                <div class="property-value" id="guke-withdrawal">False</div>
            </div>
        </div>
    </div>

    <script>
        function SafeGetValue(obj, path, defaultValue = "N/A") {
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            if (current === undefined || current === null) {
                return defaultValue;
            }
            if (Array.isArray(current)) {
                return current.length > 0 ? current[0] : defaultValue;
            }
            return current;
        }

        function updateProgressBar(barId, valueDisplayId, rawValue, min, max) {
            const progressBar = document.getElementById(barId);
            const valueDisplay = document.getElementById(valueDisplayId);
            const numericValue = parseFloat(String(rawValue));

            if (valueDisplay) {
                valueDisplay.innerText = `${numericValue} / ${max}`;
            }

            if (progressBar && !isNaN(numericValue)) {
                const clampedValue = Math.max(min, Math.min(max, numericValue));
                const range = max - min;
                const percentage = range === 0 ? 100 : ((clampedValue - min) / range) * 100;
                progressBar.style.width = `${percentage}%`;
            }
        }

        async function initDisplay() {
            try {
                if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') {
                     document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>错误: 核心数据接口未定义</p>";
                     return;
                }
                const messages = await getChatMessages(getCurrentMessageId());
                if (!messages || messages.length === 0 || !messages[0].data) {
                    return;
                }
                const gameData = messages[0].data;
                const characterData = gameData.display_data || gameData.stat_data;
                if (!characterData) {
                    return;
                }

                const characterKey = "顾客";

                if (characterData.hasOwnProperty(characterKey)) {
                    const statusElem = document.getElementById('guke-status');
                    if (statusElem) {
                        statusElem.innerText = SafeGetValue(characterData, `${characterKey}.驯化状态`, "N/A");
                    }

                    const withdrawalElem = document.getElementById('guke-withdrawal');
                    if (withdrawalElem) {
                         const withdrawalValue = SafeGetValue(characterData, `${characterKey}.戒断反应`, false);
                         withdrawalElem.innerText = String(withdrawalValue).charAt(0).toUpperCase() + String(withdrawalValue).slice(1);
                    }

                    const domesticationValue = SafeGetValue(characterData, `${characterKey}.驯化值`, 0);
                    updateProgressBar('guke-value-bar', 'guke-value', domesticationValue, 0, 100);

                }
            } catch (error) {
                document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
            }
        }
        document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
</body>
</html>
